from pathlib import Path
import shutil

src = Path('caso001/index.html')
adapter = Path('caso001/p2-multiplayer-adapter.js')
outdir = Path('caso001-rev01')
outdir.mkdir(exist_ok=True)
shutil.copy2(adapter, outdir/'p2-multiplayer-adapter.js')
s = src.read_text(encoding='utf-8')

# Preview title only; production route remains untouched.
s = s.replace('<title>EXPEDIENTES · Caso 001 — La Última Reunión</title>', '<title>EXPEDIENTES · Caso 001 — La Última Reunión · Rev01 Preview</title>', 1)

# Point printable kit to production kit while Rev01 remains isolated.
s = s.replace('href="./printables/"', 'href="../caso001/printables/"', 1)

# Upgrade header without changing any functional IDs.
old_header = '''<header class="top"><div><div class="brand">EXPEDIENTES · CASO 001</div><h1>La Última Reunión</h1><div class="subtitle">Investigación multijugador. Reúnan las evidencias, contrasten testimonios y reconstruyan qué ocurrió antes de bloquear la acusación final.</div></div><a class="tag" href="../caso001/printables/" target="_blank" rel="noopener">KIT IMPRIMIBLE</a></header>'''
new_header = '''<header class="top revTop"><div class="revBrandBlock"><div class="caseKicker">ARCHIVO CONFIDENCIAL · EXPEDIENTES</div><div class="revTitleRow"><div><div class="brand">CASO 001</div><h1>La Última Reunión</h1></div><div class="caseStamp">CASO<br>ABIERTO</div></div><div class="subtitle">Seis personas. Una reunión que terminó mal. Versiones cruzadas, rastros incompletos y una verdad que solo aparece cuando las evidencias se conectan.</div><div class="caseRule"><span>PERSONA</span><b>+</b><span>ESCENA</span><b>+</b><span>OBJETO</span><b>+</b><span>MOTIVO</span></div></div><div class="revTopActions"><span class="previewBadge">REV01 · PREVIEW</span><a class="tag" href="../caso001/printables/" target="_blank" rel="noopener">KIT IMPRIMIBLE</a></div></header>'''
if old_header not in s:
    raise SystemExit('header anchor not found')
s = s.replace(old_header, new_header, 1)

# Add dossier intro before setup. Generic text: compatible with every Crime Pack.
setup_anchor = '<section id="setup" class="panel setup">'
intro = '''<section class="dossierIntro"><div class="dossierLabel">EXPEDIENTE PRELIMINAR</div><div class="dossierGrid"><div><div class="typeLine">CLASIFICACIÓN: INVESTIGACIÓN GRUPAL</div><h2>Antes de abrir la sala</h2><p>Elegí quién vas a representar. Cada persona conserva una versión distinta de la noche y, a medida que avance el expediente, aparecerán nuevos documentos públicos y privados.</p></div><div class="dossierNote"><b>REGLA DE CAMPO</b><span>No alcanza con señalar a alguien. El equipo deberá reconstruir responsable, escena, objeto y motivo antes de sellar la acusación.</span></div></div></section>\n'''
if setup_anchor not in s:
    raise SystemExit('setup anchor not found')
s = s.replace(setup_anchor, intro + setup_anchor, 1)

# Character cards become dossier cards, while retaining character indices and IDs.
old_build = '''function buildCharacters(){\n $('#characterGrid').innerHTML=P2_LABELS.characters.map((name,i)=>`<button class="char ${i===selectedCharacter?'selected':''}" data-char="${i}"><strong>${esc(name)}</strong><small>${P2_LABELS.characterIds[i]}</small></button>`).join('');\n $('#characterGrid').querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>{selectedCharacter=Number(b.dataset.char);buildCharacters()});\n}'''
new_build = '''const REV01_PROFILES=['Socio del estudio','Consultora externa','Administración y accesos','Colaborador técnico','Asistente del encuentro','Invitado vinculado al caso'];\nfunction buildCharacters(){\n $('#characterGrid').innerHTML=P2_LABELS.characters.map((name,i)=>`<button class="char dossierChar ${i===selectedCharacter?'selected':''}" data-char="${i}"><span class="portraitPlaceholder"><span>${esc(name.slice(0,1))}</span><em>PERSONA ${String(i+1).padStart(2,'0')}</em></span><span class="charMeta"><strong>${esc(name)}</strong><small>${esc(REV01_PROFILES[i])}</small><i>${P2_LABELS.characterIds[i]}</i></span></button>`).join('');\n $('#characterGrid').querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>{selectedCharacter=Number(b.dataset.char);buildCharacters()});\n}'''
if old_build not in s:
    raise SystemExit('buildCharacters anchor not found')
s = s.replace(old_build, new_build, 1)

# Add a non-invasive visual shell AFTER the existing styles.
marker = '</style>\n</head>'
rev_css = r'''</style>
<style id="rev01-shell">
:root{--rev-bg:#080706;--rev-panel:#14110f;--rev-panel2:#1a1612;--rev-paper:#d2b58a;--rev-paper2:#ead8b8;--rev-red:#a62424;--rev-red2:#681818;--rev-gold:#d0a158;--rev-line:#4b3927;--rev-ink:#f0e6d8;--rev-muted:#ad9e8d}
html{background:#060606}
body{background:radial-gradient(circle at 16% -8%,#302015 0,#100d0a 28%,#070706 64%,#050505 100%);color:var(--rev-ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif}
body:before{content:"";position:fixed;inset:0;pointer-events:none;z-index:-1;background:repeating-linear-gradient(0deg,rgba(255,255,255,.012) 0 1px,transparent 1px 3px),linear-gradient(90deg,rgba(130,83,44,.03),transparent 32%,rgba(120,35,30,.025));opacity:.8}
.wrap{max-width:1320px;padding-top:16px}.top{border-bottom:1px solid #5a412a;padding:12px 2px 22px}.revTop{align-items:flex-start}.revBrandBlock{max-width:900px}.caseKicker{font-size:10px;letter-spacing:.28em;color:#a99376;font-weight:900}.revTitleRow{display:flex;align-items:flex-start;gap:22px;margin-top:7px}.brand{color:var(--rev-red);font-size:13px;letter-spacing:.22em}.revTitleRow h1{font-family:Impact,'Arial Narrow',Haettenschweiler,sans-serif;text-transform:uppercase;letter-spacing:.018em;font-size:clamp(48px,8vw,92px);line-height:.83;color:#efe4d5;text-shadow:0 4px 26px rgba(0,0,0,.4);margin:7px 0 12px}.caseStamp{border:3px solid #9f2826;color:#d64c43;padding:8px 12px;transform:rotate(-4deg);font-weight:950;letter-spacing:.13em;line-height:1.05;text-align:center;margin-top:12px;box-shadow:inset 0 0 0 1px #551b19}.subtitle{color:#c8b8a7;max-width:780px;font-size:15px}.caseRule{display:flex;gap:9px;flex-wrap:wrap;align-items:center;margin-top:15px;font-size:11px;font-weight:950;letter-spacing:.11em}.caseRule span{border:1px solid #62482d;background:#17120e;color:#e7c98f;border-radius:5px;padding:7px 9px}.caseRule b{color:#9a7960}.revTopActions{display:flex;align-items:flex-end;gap:8px;flex-direction:column}.previewBadge{border:1px dashed #7b6040;color:#bfa77f;padding:6px 9px;font-size:10px;letter-spacing:.14em}.tag{border-radius:6px;border-color:#684e32;background:#17120e;color:#e7c98f}.panel{background:linear-gradient(180deg,rgba(22,18,15,.98),rgba(12,11,10,.98));border-color:var(--rev-line);border-radius:13px;box-shadow:0 17px 48px rgba(0,0,0,.32)}.setup{max-width:none;margin-top:12px;border-top:3px solid #7f211f}.dossierIntro{margin-top:18px;background:linear-gradient(135deg,#d7be97,#b99469);color:#211a13;border:1px solid #6d5336;border-radius:5px;padding:18px 20px;box-shadow:0 12px 32px rgba(0,0,0,.3);position:relative;overflow:hidden}.dossierIntro:after{content:"CONFIDENCIAL";position:absolute;right:-10px;bottom:18px;border:3px solid rgba(126,32,29,.42);color:rgba(126,32,29,.5);padding:7px 12px;transform:rotate(-8deg);font-weight:950;letter-spacing:.16em;font-size:20px}.dossierLabel,.typeLine{font-size:10px;letter-spacing:.16em;font-weight:950;color:#6b241f}.dossierGrid{display:grid;grid-template-columns:1.4fr .6fr;gap:24px;align-items:center}.dossierGrid h2{font-family:Georgia,serif;font-size:30px;margin:5px 0 7px;color:#1e1711}.dossierGrid p{margin:0;max-width:760px;line-height:1.55}.dossierNote{background:rgba(58,39,23,.12);border-left:4px solid #8c2722;padding:12px 13px;display:grid;gap:5px}.dossierNote b{font-size:11px;letter-spacing:.12em;color:#6b211d}.dossierNote span{font-size:12px;line-height:1.45}.seg button,.btn{border-radius:6px;background:#191512;border-color:#59422d}.seg button.active,.btn.primary{background:linear-gradient(#a52b27,#721b18);color:#fff4e8;border-color:#c3483f;box-shadow:inset 0 0 0 1px rgba(255,255,255,.05)}.field input,.field select,.field textarea{border-radius:6px;background:#0c0b0a;border-color:#584536}.field label{color:#a99987}.characters{grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.dossierChar{display:grid;grid-template-columns:92px 1fr;gap:0;padding:0;overflow:hidden;border-radius:7px;background:#0e0d0c;border:1px solid #665035;min-height:118px;box-shadow:0 8px 22px rgba(0,0,0,.26)}.dossierChar:hover{transform:translateY(-2px);border-color:#b1844f}.dossierChar.selected{border-color:#d0a158;box-shadow:0 0 0 2px #8b672f,0 8px 24px rgba(0,0,0,.3)}.portraitPlaceholder{position:relative;background:radial-gradient(circle at 50% 32%,#6e6255 0,#302b26 37%,#0d0d0c 72%);display:grid;place-items:center;border-right:1px solid #5b4631;min-height:118px;overflow:hidden}.portraitPlaceholder:after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 3px,rgba(255,255,255,.025) 3px 4px)}.portraitPlaceholder span{font-family:Georgia,serif;font-size:46px;color:#c4ae8e;opacity:.83}.portraitPlaceholder em{position:absolute;left:6px;bottom:6px;font-style:normal;font-size:8px;letter-spacing:.08em;color:#dbc99f;background:#0b0907cc;border:1px solid #796041;padding:3px 5px}.charMeta{padding:13px 12px;display:flex;flex-direction:column;justify-content:center;text-align:left}.charMeta strong{font-family:Georgia,serif;font-size:21px;color:#f1e4d4}.charMeta small{color:#c0ad97;margin-top:5px;line-height:1.25}.charMeta i{font-style:normal;font-size:9px;letter-spacing:.13em;color:#8f7d69;margin-top:10px}.roomHead{border-bottom:1px solid #463421;padding-bottom:9px}.code{color:#e0b767;text-shadow:0 0 24px rgba(208,161,88,.12)}.pill{border-radius:5px;border-color:#4f3c2c;background:#15110e}.player{border-radius:7px;border-color:#4b3929;background:#11100f}.player:not(.npc){border-left:4px solid #9d2a26}.npc{border-color:#51483d;background:#0f0e0d}.statusbar{background:#0d0c0b;border-top:1px solid #493624;border-bottom:1px solid #493624;padding:13px 10px}.clock{font-family:Impact,'Arial Narrow',sans-serif;letter-spacing:.05em;color:#e1c17d}.stage b{color:#cda153}.evidence{border-radius:5px;background:linear-gradient(135deg,#d6be99,#b9976d);border:1px solid #72593d;border-left:5px solid #8d2823;color:#221a13;box-shadow:0 8px 18px rgba(0,0,0,.2)}.evidence small{color:#5b4837}.evidence.private{background:linear-gradient(135deg,#1b1817,#101010);color:#eee0d0;border-color:#58412e;border-left-color:#bf8b43}.evidence.private small{color:#b9a48f}.evidence.npc{border-left-color:#65517c}.role{border-radius:6px;background:#100f0e;border-color:#544232}.board .chip{border-radius:5px;background:#12100e;border-color:#54412e}.chip.sus{border-color:#b62f2a;color:#f3c69e;background:#21110f}.timeline{max-height:520px}.event{border-left-color:#8b2925;color:#d7cabd}.director{background:#19130d;border-color:#73552e}.solution,.accLocked{border-radius:6px}.toast{border-radius:6px;background:#17120f;border-color:#6d5236}.muted{color:var(--rev-muted)}
@media(max-width:900px){.dossierGrid{grid-template-columns:1fr}.dossierIntro:after{font-size:15px;right:-20px}.revTop{display:grid}.revTopActions{align-items:flex-start;flex-direction:row}.characters{grid-template-columns:repeat(2,1fr)}}
@media(max-width:560px){.revTitleRow{gap:10px}.caseStamp{font-size:10px;padding:6px}.dossierChar{grid-template-columns:78px 1fr;min-height:100px}.portraitPlaceholder{min-height:100px}.portraitPlaceholder span{font-size:38px}.characters{grid-template-columns:1fr}.dossierIntro{padding:15px}.dossierGrid h2{font-size:24px}.caseRule{gap:5px}.caseRule span{font-size:9px;padding:6px}.previewBadge{display:none}}
</style>
</head>'''
if marker not in s:
    raise SystemExit('style marker not found')
s = s.replace(marker, rev_css, 1)

# Keep cache isolated from production and identify preview adapter version.
s = s.replace("./p2-multiplayer-adapter.js?v=20260919-2045", "./p2-multiplayer-adapter.js?v=rev01-shell-1", 1)

(outdir/'index.html').write_text(s, encoding='utf-8')
print('CASO001 REV01 shell built')
